        {
            // Timber jetty — restrained silhouette so kit coast/dunes stay the hero read.
            var timber = new Color(0.45f, 0.32f, 0.18f);
            var pile = new Color(0.35f, 0.26f, 0.16f);
            CreateBlock("Jetty deck NWN", new Vector3(-18.57f, -0.154f, -49.9415f), new Vector3(1.1155f, 0.1659f, 1.8624f), timber);
            CreateBlock("Jetty deck NWS", new Vector3(-18.53f, -0.152f, -48.0985f), new Vector3(1.1155f, 0.1659f, 1.8624f), timber);
            CreateBlock("Jetty deck NEN", new Vector3(-17.47f, -0.152f, -49.9015f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.98f));
            CreateBlock("Jetty deck NES", new Vector3(-17.43f, -0.15f, -48.0585f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.98f));
            CreateBlock("Jetty deck mid W", new Vector3(-18.55f, -0.149f, -52.52f), new Vector3(1.1f, 0.165f, 1.85f), Shade(timber, 0.96f));
            CreateBlock("Jetty deck mid E", new Vector3(-17.45f, -0.147f, -52.48f), new Vector3(1.1f, 0.165f, 1.85f), Shade(timber, 0.965f));
            CreateBlock("Jetty deck", new Vector3(-18f, -0.146f, -51.4f), new Vector3(2.1f, 0.16f, 1.7f), Shade(timber, 0.968f));
            CreateBlock("Jetty deck mid S", new Vector3(-18f, -0.148f, -53.6f), new Vector3(2.1f, 0.16f, 1.7f), Shade(timber, 0.955f));
            CreateBlock("Jetty deck SWN", new Vector3(-18.57f, -0.154f, -56.9415f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.94f));
            CreateBlock("Jetty deck SWS", new Vector3(-18.53f, -0.152f, -55.0985f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.94f));
            CreateBlock("Jetty deck SEN", new Vector3(-17.47f, -0.152f, -56.9015f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.93f));
            CreateBlock("Jetty deck SES", new Vector3(-17.43f, -0.15f, -55.0585f), new Vector3(1.1155f, 0.1659f, 1.8624f), Shade(timber, 0.93f));
            for (var plank = 0; plank < 6; plank++)
            {
                var z = -46.5f - plank * 1.9f;
                CreateBlock($"Jetty plank {plank}", new Vector3(-18f, -0.04f, z), new Vector3(2.2f, 0.05f, 1.35f), Shade(timber, 0.92f + (plank % 2) * 0.04f));
            }

            for (var i = 0; i < 3; i++)
            {
                var z = -47f - i * 3.5f;
                CreateBlock($"Jetty pile L {i}", new Vector3(-19f, -0.55f, z), new Vector3(0.28f, 0.9f, 0.28f), pile);
                CreateBlock($"Jetty pile R {i}", new Vector3(-17f, -0.55f, z), new Vector3(0.28f, 0.9f, 0.28f), pile);
            }

            CreateBlock("Jetty rail L N", new Vector3(-19.1f, 0.35f, -49f), new Vector3(0.08f, 0.7f, 4f), Shade(timber, 0.85f));
            CreateBlock("Jetty rail L S", new Vector3(-19.1f, 0.35f, -55f), new Vector3(0.08f, 0.7f, 4f), Shade(timber, 0.85f));
            CreateBlock("Jetty rail R N", new Vector3(-16.9f, 0.35f, -49f), new Vector3(0.08f, 0.7f, 4f), Shade(timber, 0.85f));
            CreateBlock("Jetty rail R S", new Vector3(-16.9f, 0.35f, -55f), new Vector3(0.08f, 0.7f, 4f), Shade(timber, 0.85f));
            CreateBlock("Jetty bollard A", new Vector3(-19.0f, 0.25f, -46.5f), new Vector3(0.22f, 0.55f, 0.22f), new Color(0.25f, 0.26f, 0.28f));
            CreateBlock("Jetty bollard B", new Vector3(-17.0f, 0.25f, -46.5f), new Vector3(0.22f, 0.55f, 0.22f), new Color(0.25f, 0.26f, 0.28f));
            CreateBlock("Jetty end cap", new Vector3(-18f, -0.05f, -58f), new Vector3(2.5f, 0.2f, 0.35f), Shade(timber, 0.8f));
